install/bootstrap/dispatch.ps1:
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('devloop', 'devloop-plan', 'update', 'uninstall')]
    [string] $Command,

    [string] $ArgumentsJson = '[]'
)

$ErrorActionPreference = 'Stop'
$InstallRoot = Split-Path -Parent $PSScriptRoot
$BootstrapRoot = $PSScriptRoot
try {
    $RemainingArgs = @($ArgumentsJson | ConvertFrom-Json)
}
catch {
    throw 'Dev Loop bootstrap received invalid encoded arguments.'
}

function Assert-PlainDirectory {
    param([string] $Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Container)) {
        throw "Dev Loop bootstrap directory is missing: $Path"
    }
    $item = Get-Item -LiteralPath $Path -Force
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
        throw "Dev Loop bootstrap rejected a reparse point: $Path"
    }
}

function Get-DirectoryFingerprint {
    param([string] $Path)

    Assert-PlainDirectory -Path $Path
    $files = @((Get-ChildItem -LiteralPath $Path -File -Recurse -Force).FullName)
    [Array]::Sort($files, [StringComparer]::Ordinal)
    $entries = foreach ($file in $files) {
        $item = Get-Item -LiteralPath $file -Force
        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
            throw "Dev Loop bootstrap rejected a reparse point: $file"
        }
        $relative = $file.Substring($Path.TrimEnd('\').Length + 1).Replace('\', '/')
        "$relative=$((Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash)"
    }
    $algorithm = [Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes($entries -join "`n")
        return [BitConverter]::ToString($algorithm.ComputeHash($bytes)).Replace('-', '')
    }
    finally {
        $algorithm.Dispose()
    }
}

function Get-TrackedFingerprint {
    param([string] $Root)
    $entries = @(& git -C $Root ls-files --stage)
    if ($LASTEXITCODE -ne 0) { throw 'Dev Loop bootstrap could not enumerate release files.' }
    [Array]::Sort($entries, [StringComparer]::Ordinal)
    $algorithm = [Security.Cryptography.SHA256]::Create()
    try {
        return [BitConverter]::ToString($algorithm.ComputeHash([Text.Encoding]::UTF8.GetBytes($entries -join "`n"))).Replace('-', '')
    }
    finally { $algorithm.Dispose() }
}

function Read-StrictJson {
    param([string] $Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "Dev Loop bootstrap metadata is missing: $Path"
    }
    $item = Get-Item -LiteralPath $Path -Force
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
        throw "Dev Loop bootstrap rejected a reparse point: $Path"
    }
    try {
        return Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json
    }
    catch {
        throw "Dev Loop bootstrap metadata is unreadable: $Path"
    }
}

Assert-PlainDirectory -Path $InstallRoot
Assert-PlainDirectory -Path $BootstrapRoot
$pointer = Read-StrictJson -Path (Join-Path $BootstrapRoot 'current.json')
$pointerFields = @($pointer.PSObject.Properties.Name | Sort-Object)
if (($pointerFields -join ',') -ne 'commit,release_path,runtime_fingerprint,tracked_fingerprint,version') {
    throw 'Dev Loop bootstrap current pointer has an unsupported schema.'
}
if ($pointer.version -ne 1 -or $pointer.commit -cnotmatch '^[0-9a-f]{40}$') {
    throw 'Dev Loop bootstrap current pointer has an invalid release identity.'
}
$expectedRelative = "releases/$($pointer.commit)"
if ($pointer.release_path -cne $expectedRelative) {
    throw 'Dev Loop bootstrap current pointer has a non-canonical release path.'
}
$releaseRoot = Join-Path $InstallRoot ($pointer.release_path.Replace('/', '\'))
$canonicalRelease = [IO.Path]::GetFullPath($releaseRoot)
$expectedRelease = [IO.Path]::GetFullPath((Join-Path $InstallRoot "releases\$($pointer.commit)"))
if (-not [string]::Equals($canonicalRelease, $expectedRelease, [StringComparison]::OrdinalIgnoreCase)) {
    throw 'Dev Loop bootstrap current pointer escapes the managed releases directory.'
}
Assert-PlainDirectory -Path (Join-Path $InstallRoot 'releases')
Assert-PlainDirectory -Path $releaseRoot
$manifest = Read-StrictJson -Path (Join-Path $BootstrapRoot "release-$($pointer.commit).json")
if (
    $manifest.version -ne 1 -or
    $manifest.commit -cne $pointer.commit -or
    $manifest.release_path -cne $pointer.release_path -or
    $manifest.tracked_fingerprint -cne $pointer.tracked_fingerprint -or
    $manifest.runtime_fingerprint -cne $pointer.runtime_fingerprint
) {
    throw 'Dev Loop bootstrap release manifest does not match the current pointer.'
}
$actualCommit = (& git -C $releaseRoot rev-parse HEAD).Trim()
if ($LASTEXITCODE -ne 0 -or $actualCommit -cne $pointer.commit) {
    throw 'Dev Loop bootstrap release commit does not match the current pointer.'
}
& git -C $releaseRoot diff --quiet --
if ($LASTEXITCODE -ne 0) { throw 'Dev Loop bootstrap current release has tracked changes.' }
& git -C $releaseRoot diff --cached --quiet --
if ($LASTEXITCODE -ne 0) { throw 'Dev Loop bootstrap current release has staged changes.' }
$unexpected = @(& git -C $releaseRoot ls-files --others --exclude-standard | Where-Object { -not $_.Replace('\', '/').StartsWith('.venv/') })
if ($LASTEXITCODE -ne 0 -or $unexpected.Count -ne 0) {
    throw 'Dev Loop bootstrap current release has unexpected untracked content.'
}
if ((Get-TrackedFingerprint -Root $releaseRoot) -cne $pointer.tracked_fingerprint) {
    throw 'Dev Loop bootstrap tracked release fingerprint does not match its manifest.'
}
$runtimeRoot = Join-Path $releaseRoot '.venv'
if ((Get-DirectoryFingerprint -Path $runtimeRoot) -cne $pointer.runtime_fingerprint) {
    throw 'Dev Loop bootstrap current runtime fingerprint does not match its manifest.'
}

$target = switch ($Command) {
    'devloop' { Join-Path $releaseRoot 'bin\devloop.ps1' }
    'devloop-plan' { Join-Path $releaseRoot 'bin\devloop-plan.ps1' }
    'update' { Join-Path $releaseRoot 'install\devloop.ps1' }
    'uninstall' { Join-Path $releaseRoot 'install\uninstall-devloop.ps1' }
}
if (-not (Test-Path -LiteralPath $target -PathType Leaf)) {
    throw "Dev Loop bootstrap command is missing from the current release: $target"
}
if ($Command -in @('update', 'uninstall')) {
    & pwsh -NoProfile -ExecutionPolicy Bypass -File $target -InstallDir $InstallRoot @RemainingArgs
}
else {
    & pwsh -NoProfile -ExecutionPolicy Bypass -File $target @RemainingArgs
}
exit $LASTEXITCODE

install/bootstrap/dispatch.sh:
#!/usr/bin/env bash
set -euo pipefail
COMMAND="${1:?command is required}"
shift
INSTALL_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
find_python() { for p in python3 python; do command -v "$p" >/dev/null 2>&1 && "$p" -c 'import sys; raise SystemExit(0 if sys.version_info >= (3,10) else 1)' >/dev/null 2>&1 && { printf '%s\n' "$p"; return; }; done; return 1; }
PYTHON="$(find_python)" || { printf 'devloop-bootstrap: error: Python 3.10+ is required\n' >&2; exit 1; }
RELEASE_ROOT="$($PYTHON "$INSTALL_ROOT/bootstrap/verify.py" "$INSTALL_ROOT")"
case "$COMMAND" in
  devloop) TARGET="$RELEASE_ROOT/bin/devloop.sh" ;;
  devloop-plan) TARGET="$RELEASE_ROOT/bin/devloop-plan.sh" ;;
  update) TARGET="$RELEASE_ROOT/install/devloop.sh"; set -- --dir "$INSTALL_ROOT" "$@" ;;
  uninstall)
    bash "$RELEASE_ROOT/install/uninstall-devloop.sh" --dir "$INSTALL_ROOT" --capabilities-only "$@"
    exec "$PYTHON" "$INSTALL_ROOT/bootstrap/transaction.py" uninstall "$INSTALL_ROOT"
    ;;
  *) printf 'devloop-bootstrap: error: unsupported command: %s\n' "$COMMAND" >&2; exit 1 ;;
esac
[ -f "$TARGET" ] || { printf 'devloop-bootstrap: error: current command is missing: %s\n' "$TARGET" >&2; exit 1; }
exec bash "$TARGET" "$@"

