from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import sys
import uuid
from pathlib import Path

from verify import (
    _directory_fingerprint,
    _git,
    _plain,
    _tracked_fingerprint,
    verify,
    verify_release,
)

ASSETS = (
    ("dispatch.ps1", "bootstrap/dispatch.ps1"),
    ("dispatch.sh", "bootstrap/dispatch.sh"),
    ("verify.py", "bootstrap/verify.py"),
    ("transaction.py", "bootstrap/transaction.py"),
    ("bin/devloop.ps1", "bin/devloop.ps1"),
    ("bin/devloop-plan.ps1", "bin/devloop-plan.ps1"),
    ("bin/devloop.sh", "bin/devloop.sh"),
    ("bin/devloop-plan.sh", "bin/devloop-plan.sh"),
    ("install/devloop.ps1", "install/devloop.ps1"),
    ("install/uninstall-devloop.ps1", "install/uninstall-devloop.ps1"),
    ("install/devloop.sh", "install/devloop.sh"),
    ("install/uninstall-devloop.sh", "install/uninstall-devloop.sh"),
)
POINTER_FIELDS = {
    "version", "commit", "release_path", "tracked_fingerprint", "runtime_fingerprint"
}
JOURNAL_FIELDS = POINTER_FIELDS | {"install_root", "candidate_path", "phase", "previous_pointer"}


def _atomic_json(path: Path, value: dict[str, object]) -> None:
    temporary = path.with_name(f"{path.name}.next-{uuid.uuid4().hex}")
    with temporary.open("w", encoding="utf-8", newline="\n") as stream:
        json.dump(value, stream, separators=(",", ":"), sort_keys=True)
        stream.write("\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)
    if os.name != "nt":
        descriptor = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest().upper()


def _remove_read_only(function: object, path: str, _: object) -> None:
    os.chmod(path, stat.S_IWRITE)
    function(path)  # type: ignore[operator]


def _interrupt(phase: str) -> None:
    if os.environ.get("DEVLOOP_TESTING") == "1" and os.environ.get(
        "DEVLOOP_TEST_INTERRUPT_AFTER_PHASE"
    ) == phase:
        os._exit(91)


def _write_journal(install: Path, journal: dict[str, object], phase: str) -> None:
    journal["phase"] = phase
    _atomic_json(install / "bootstrap" / "install-transaction.json", journal)
    _interrupt(phase)


def _release_evidence(root: Path, commit: str) -> dict[str, object]:
    _plain(root)
    if _git(root, "rev-parse", "HEAD").strip() != commit:
        raise RuntimeError("release commit changed during validation")
    _git(root, "diff", "--quiet", "--")
    _git(root, "diff", "--cached", "--quiet", "--")
    unexpected = [
        item for item in _git(root, "ls-files", "--others", "--exclude-standard").splitlines()
        if not item.replace("\\", "/").startswith(".venv/")
    ]
    if unexpected:
        raise RuntimeError("release has unexpected untracked content")
    return {
        "version": 1,
        "commit": commit,
        "release_path": f"releases/{commit}",
        "tracked_fingerprint": _tracked_fingerprint(root),
        "runtime_fingerprint": _directory_fingerprint(root / ".venv"),
    }


def _initialize_bootstrap(install: Path, candidate: Path) -> None:
    template = candidate / "install" / "bootstrap"
    for relative in ("bootstrap/legacy-assets", "releases", "bin", "install"):
        path = install / relative
        path.mkdir(parents=True, exist_ok=True)
        _plain(path)
    layout_path = install / "bootstrap" / "layout.json"
    if layout_path.exists():
        layout = json.loads(layout_path.read_text(encoding="utf-8"))
        if layout.get("version") != 1:
            raise RuntimeError("unsupported bootstrap layout version")
        for _, relative in ASSETS:
            target = install / relative
            if _sha256(target) != layout["assets"].get(relative):
                raise RuntimeError(f"stable bootstrap asset was modified: {relative}")
        return
    assets: dict[str, str] = {}
    backups: list[str] = []
    for source_relative, target_relative in ASSETS:
        source = template / source_relative
        target = install / target_relative
        _plain(source)
        if target.exists():
            backup = install / "bootstrap" / "legacy-assets" / target_relative
            backup.parent.mkdir(parents=True, exist_ok=True)
            if not backup.exists():
                shutil.copy2(target, backup)
            backups.append(target_relative)
        shutil.copy2(source, target)
        if target.suffix in {".sh", ""}:
            target.chmod(target.stat().st_mode | 0o111)
        assets[target_relative] = _sha256(target)
    _atomic_json(layout_path, {"version": 1, "assets": assets, "legacy_backups": backups})


def _journal(install: Path) -> dict[str, object] | None:
    path = install / "bootstrap" / "install-transaction.json"
    if not path.exists():
        return None
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict) or set(value) != JOURNAL_FIELDS:
        raise RuntimeError("installation journal has an unsupported schema")
    commit = value["commit"]
    if not isinstance(commit, str) or re.fullmatch(r"[0-9a-f]{40}", commit) is None:
        raise RuntimeError("installation journal has an invalid commit")
    if Path(str(value["install_root"])) != install:
        raise RuntimeError("installation journal root mismatch")
    if Path(str(value["release_path"])) != install / "releases" / commit:
        raise RuntimeError("installation journal release path is not owned")
    candidate = Path(str(value["candidate_path"]))
    expected_candidate_prefix = f".{install.name}.candidate-"
    if candidate.parent != install.parent or not candidate.name.startswith(
        expected_candidate_prefix
    ):
        raise RuntimeError("installation journal candidate path is not owned")
    return value


def prepare(install: Path, candidate: Path, commit: str) -> Path:
    install = install.absolute()
    candidate = candidate.absolute()
    if _journal(install) is not None:
        raise RuntimeError("an unfinished installation transaction requires recovery")
    evidence = _release_evidence(candidate, commit)
    _initialize_bootstrap(install, candidate)
    release = install / "releases" / commit
    if release.exists():
        raise RuntimeError("canonical release already exists without a transaction")
    previous = None
    current_path = install / "bootstrap" / "current.json"
    if current_path.exists():
        verify(install)
        previous = json.loads(current_path.read_text(encoding="utf-8"))
    journal = dict(evidence)
    journal.update(
        install_root=str(install), candidate_path=str(candidate), release_path=str(release),
        previous_pointer=previous, phase="prepared"
    )
    _write_journal(install, journal, "prepared")
    candidate.rename(release)
    _atomic_json(install / "bootstrap" / f"release-{commit}.json", evidence)
    _write_journal(install, journal, "release_ready")
    return release


def recover(install: Path) -> tuple[str, Path | None]:
    install = install.absolute()
    journal = _journal(install)
    if journal is None:
        return "NONE", None
    release = Path(str(journal["release_path"]))
    phase = str(journal["phase"])
    if phase == "prepared":
        candidate = Path(str(journal["candidate_path"]))
        evidence = _release_evidence(candidate, str(journal["commit"]))
        for field in ("tracked_fingerprint", "runtime_fingerprint"):
            if evidence[field] != journal[field]:
                raise RuntimeError("prepared candidate fingerprint mismatch")
        candidate.rename(release)
        manifest = {field: journal[field] for field in POINTER_FIELDS}
        manifest["release_path"] = f"releases/{journal['commit']}"
        _atomic_json(install / "bootstrap" / f"release-{journal['commit']}.json", manifest)
        _write_journal(install, journal, "release_ready")
        phase = "release_ready"
    if phase in {"release_ready", "adopted"}:
        return "NEEDS_ADOPTION" if phase == "release_ready" else "READY_TO_SWITCH", release
    if phase in {"switched", "committed"}:
        verify(install)
        (install / "bootstrap" / "install-transaction.json").unlink()
        return "COMPLETE", release
    raise RuntimeError("installation journal phase is unsupported")


def commit(install: Path) -> None:
    install = install.absolute()
    journal = _journal(install)
    if journal is None:
        raise RuntimeError("installation journal is missing")
    release = Path(str(journal["release_path"]))
    evidence = _release_evidence(release, str(journal["commit"]))
    for field in ("tracked_fingerprint", "runtime_fingerprint"):
        if evidence[field] != journal[field]:
            raise RuntimeError("immutable release fingerprint mismatch")
    if journal["phase"] == "release_ready":
        _write_journal(install, journal, "adopted")
    previous = journal["previous_pointer"]
    if isinstance(previous, dict) and previous.get("commit") != journal["commit"]:
        verify(install)
        _atomic_json(install / "bootstrap" / "previous.json", previous)
    pointer = {field: journal[field] for field in POINTER_FIELDS}
    pointer["release_path"] = f"releases/{journal['commit']}"
    _atomic_json(install / "bootstrap" / "current.json", pointer)
    _write_journal(install, journal, "switched")
    _write_journal(install, journal, "committed")
    verify(install)
    (install / "bootstrap" / "install-transaction.json").unlink()


def rollback(install: Path) -> None:
    install = install.absolute()
    if _journal(install) is not None:
        raise RuntimeError("finish the pending update before rollback")
    current_path = install / "bootstrap" / "current.json"
    previous_path = install / "bootstrap" / "previous.json"
    current = json.loads(current_path.read_text(encoding="utf-8"))
    previous = json.loads(previous_path.read_text(encoding="utf-8"))
    for name, pointer in (("current", current), ("previous", previous)):
        if not isinstance(pointer, dict) or set(pointer) != POINTER_FIELDS:
            raise RuntimeError(f"{name} release pointer has an unsupported schema")
        commit_value = pointer["commit"]
        if not isinstance(commit_value, str):
            raise RuntimeError(f"{name} release pointer has an invalid commit")
        release = verify_release(install.resolve(strict=True), commit_value)
        evidence = _release_evidence(release, commit_value)
        for field in POINTER_FIELDS:
            if evidence[field] != pointer[field]:
                raise RuntimeError(f"{name} release fingerprint mismatch")
    _atomic_json(current_path, previous)
    _atomic_json(previous_path, current)


def uninstall_layout(install: Path) -> None:
    install = install.absolute()
    verify(install)
    bootstrap = install / "bootstrap"
    layout = json.loads((bootstrap / "layout.json").read_text(encoding="utf-8"))
    if layout.get("version") != 1 or not isinstance(layout.get("assets"), dict):
        raise RuntimeError("layout manifest is unsupported; nothing was removed")
    releases = install / "releases"
    owned: list[Path] = []
    for release in releases.iterdir():
        _plain(release)
        if not release.is_dir() or re.fullmatch(r"[0-9a-f]{40}", release.name) is None:
            raise RuntimeError(f"unmanaged release path blocks uninstall: {release}")
        if not (bootstrap / f"release-{release.name}.json").is_file():
            raise RuntimeError(f"release ownership manifest is missing: {release.name}")
        verify_release(install, release.name)
        owned.append(release)
    for release in owned:
        shutil.rmtree(release, onerror=_remove_read_only)
        (bootstrap / f"release-{release.name}.json").unlink()
    backup_root = bootstrap / "legacy-assets"
    for relative, expected_hash in layout["assets"].items():
        if not isinstance(relative, str) or not isinstance(expected_hash, str):
            raise RuntimeError("layout asset record is invalid")
        target = install / Path(relative)
        backup = backup_root / Path(relative)
        if target.is_file():
            _plain(target)
            if _sha256(target) == expected_hash:
                target.unlink()
            else:
                continue
        if backup.is_file():
            target.parent.mkdir(parents=True, exist_ok=True)
            backup.replace(target)
    for name in ("current.json", "previous.json", "install-transaction.json", "layout.json"):
        path = bootstrap / name
        if path.exists():
            path.unlink()
    for root, directories, _ in os.walk(install, topdown=False):
        for directory in directories:
            path = Path(root) / directory
            is_managed = (
                path == releases or path == bootstrap or path.is_relative_to(backup_root)
            )
            if path == install or not is_managed:
                continue
            try:
                path.rmdir()
            except OSError:
                pass


def main() -> int:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    prepare_parser = sub.add_parser("prepare")
    prepare_parser.add_argument("install", type=Path)
    prepare_parser.add_argument("candidate", type=Path)
    prepare_parser.add_argument("commit")
    recover_parser = sub.add_parser("recover")
    recover_parser.add_argument("install", type=Path)
    commit_parser = sub.add_parser("commit")
    commit_parser.add_argument("install", type=Path)
    uninstall_parser = sub.add_parser("uninstall")
    uninstall_parser.add_argument("install", type=Path)
    rollback_parser = sub.add_parser("rollback")
    rollback_parser.add_argument("install", type=Path)
    args = parser.parse_args()
    if args.command == "prepare":
        print(prepare(args.install, args.candidate, args.commit))
    elif args.command == "recover":
        action, release = recover(args.install)
        print(f"{action}\t{release or ''}")
    elif args.command == "commit":
        commit(args.install)
    elif args.command == "uninstall":
        uninstall_layout(args.install)
    else:
        rollback(args.install)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (
        OSError,
        ValueError,
        RuntimeError,
        json.JSONDecodeError,
        subprocess.SubprocessError,
    ) as error:
        print(f"devloop-install: error: {error}", file=sys.stderr)
        raise SystemExit(1) from error

