from __future__ import annotations

import hashlib
import json
import os
import re
import subprocess
import sys
from pathlib import Path

POINTER_FIELDS = {
    "version",
    "commit",
    "release_path",
    "tracked_fingerprint",
    "runtime_fingerprint",
}


def _plain(path: Path) -> None:
    if path.is_symlink() or (hasattr(os.path, "isjunction") and os.path.isjunction(path)):
        raise RuntimeError(f"reparse or symbolic link rejected: {path}")


def _json(path: Path) -> dict[str, object]:
    _plain(path)
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise RuntimeError(f"object metadata required: {path}")
    return value


def _directory_fingerprint(root: Path) -> str:
    _plain(root)
    entries: list[str] = []
    for path in sorted(item for item in root.rglob("*") if item.is_file()):
        _plain(path)
        relative = path.relative_to(root).as_posix()
        entries.append(f"{relative}={hashlib.sha256(path.read_bytes()).hexdigest().upper()}")
    return hashlib.sha256("\n".join(entries).encode()).hexdigest().upper()


def _git(root: Path, *args: str) -> str:
    result = subprocess.run(
        ["git", "-C", str(root), *args], capture_output=True, text=True, check=False
    )
    if result.returncode:
        raise RuntimeError(result.stderr.strip() or "git validation failed")
    return result.stdout


def _tracked_fingerprint(root: Path) -> str:
    entries = sorted(_git(root, "ls-files", "--stage").splitlines())
    return hashlib.sha256("\n".join(entries).encode()).hexdigest().upper()


def verify_release(install_root: Path, commit: str) -> Path:
    bootstrap = install_root / "bootstrap"
    pointer = _json(bootstrap / f"release-{commit}.json")
    if set(pointer) != POINTER_FIELDS or pointer["version"] != 1:
        raise RuntimeError("release manifest has an unsupported schema")
    if pointer["commit"] != commit or re.fullmatch(r"[0-9a-f]{40}", commit) is None:
        raise RuntimeError("release manifest has an invalid commit")
    if pointer["release_path"] != f"releases/{commit}":
        raise RuntimeError("release manifest has a non-canonical release path")
    release = install_root / "releases" / commit
    if release.resolve(strict=True) != release:
        raise RuntimeError("current pointer does not resolve to its canonical release")
    _plain(release)
    if _git(release, "rev-parse", "HEAD").strip() != commit:
        raise RuntimeError("release commit does not match current pointer")
    _git(release, "diff", "--quiet", "--")
    _git(release, "diff", "--cached", "--quiet", "--")
    unexpected = [
        item
        for item in _git(release, "ls-files", "--others", "--exclude-standard").splitlines()
        if not item.replace("\\", "/").startswith(".venv/")
    ]
    if unexpected:
        raise RuntimeError("release contains unexpected untracked content")
    tracked_fingerprint = _tracked_fingerprint(release)
    if tracked_fingerprint != pointer["tracked_fingerprint"]:
        raise RuntimeError(
            "tracked release fingerprint mismatch: "
            f"expected {pointer['tracked_fingerprint']}, found {tracked_fingerprint}"
        )
    if _directory_fingerprint(release / ".venv") != pointer["runtime_fingerprint"]:
        raise RuntimeError("runtime fingerprint mismatch")
    return release


def verify(install_root: Path) -> Path:
    install_root = install_root.resolve(strict=True)
    _plain(install_root)
    bootstrap = install_root / "bootstrap"
    _plain(bootstrap)
    pointer = _json(bootstrap / "current.json")
    if set(pointer) != POINTER_FIELDS or pointer["version"] != 1:
        raise RuntimeError("current pointer has an unsupported schema")
    commit = pointer["commit"]
    if not isinstance(commit, str) or re.fullmatch(r"[0-9a-f]{40}", commit) is None:
        raise RuntimeError("current pointer has an invalid commit")
    release = verify_release(install_root, commit)
    manifest = _json(bootstrap / f"release-{commit}.json")
    if manifest != pointer:
        raise RuntimeError("release manifest does not match current pointer")
    return release


if __name__ == "__main__":
    try:
        root = Path(sys.argv[1])
        release = (
            verify_release(root.resolve(strict=True), sys.argv[2])
            if len(sys.argv) > 2
            else verify(root)
        )
        print(release)
    except (OSError, ValueError, RuntimeError, json.JSONDecodeError) as error:
        print(f"devloop-bootstrap: error: {error}", file=sys.stderr)
        raise SystemExit(1) from error

install/devloop.ps1:
# Install or update Portable Dev Loop through an immutable side-by-side release.

[CmdletBinding()]
param(
    [string] $InstallDir,
    [string] $BinDir,
    [string] $RepoUrl = $(if ($env:DEVLOOP_REPO_URL) { $env:DEVLOOP_REPO_URL } else { 'https://github.com/dimitriskl/devloop.git' }),
    [string] $Ref = $(if ($env:DEVLOOP_REF) { $env:DEVLOOP_REF } else { 'main' }),
    [switch] $NoSkills,
    [switch] $NoBinLinks,
    [switch] $Rollback,
    [switch] $Help
)

$ErrorActionPreference = 'Stop'
$DefaultInstallDir = 'C:\devloop'
$LayoutVersion = 1
$JournalVersion = 1
$script:CandidateDir = $null
$script:CandidateCommit = $null
$null = $BinDir
$null = $NoBinLinks

function Write-InstallLog { param([string] $Message) Write-Host "devloop-install: $Message" }

function Show-Usage {
    @'
Usage: devloop.ps1 [options]

Install or update Portable Dev Loop using immutable side-by-side releases.

Options:
  -InstallDir PATH   Stable bootstrap directory (default: C:\devloop)
  -Ref REF           Git branch, tag, or commit (default: main)
  -RepoUrl URL       Git repository URL
  -NoSkills          Skip copying bundled Codex skills and agents
  -Rollback          Atomically select the previously current release
  -Help              Show this help
'@ | Write-Host
}

function Get-DevLoopPython {
    foreach ($candidate in @('python', 'python3', 'py')) {
        if ($null -eq (Get-Command $candidate -ErrorAction SilentlyContinue)) { continue }
        try {
            & $candidate -c 'import sys; raise SystemExit(0 if sys.version_info >= (3, 10) else 1)' *> $null
            if ($LASTEXITCODE -eq 0) { return $candidate }
        }
        catch { continue }
    }
    throw 'devloop-install: error: Python 3.10+ is required.'
}

function Resolve-InstallDirectory {
    $selected = if (-not [string]::IsNullOrWhiteSpace($InstallDir)) { $InstallDir }
    elseif (-not [string]::IsNullOrWhiteSpace($env:DEVLOOP_INSTALL_DIR)) { $env:DEVLOOP_INSTALL_DIR }
    else {
        $reply = Read-Host "Install directory [$DefaultInstallDir]"
        if ([string]::IsNullOrWhiteSpace($reply)) { $DefaultInstallDir } else { $reply }
    }
    try { return [IO.Path]::GetFullPath($selected).TrimEnd('\') }
    catch { throw "devloop-install: error: invalid install directory '$selected'" }
}

function Assert-PlainPath {
    param([string] $Path, [switch] $AllowMissing)
    if (-not (Test-Path -LiteralPath $Path)) {
        if ($AllowMissing) { return }
        throw "devloop-install: error: required path is missing: $Path"
    }
    $item = Get-Item -LiteralPath $Path -Force
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
        throw "devloop-install: error: refusing reparse point: $Path"
    }
}

function Assert-SafeInstallRoot {
    $root = [IO.Path]::GetPathRoot($InstallDir)
    if ([string]::IsNullOrWhiteSpace($root) -or $InstallDir -ieq $root.TrimEnd('\')) {
        throw 'devloop-install: error: refusing filesystem root as InstallDir'
    }
    $parent = Split-Path -Parent $InstallDir
    if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
    Assert-PlainPath -Path $parent
    Assert-PlainPath -Path $InstallDir -AllowMissing
}

function Write-DurableText {
    param([string] $Path, [string] $Content)
    $temporary = "$Path.next-$([guid]::NewGuid().ToString('N'))"
    Assert-PlainPath -Path (Split-Path -Parent $Path)
    [IO.File]::WriteAllText($temporary, $Content, [Text.UTF8Encoding]::new($false))
    $stream = [IO.File]::Open($temporary, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
    try { $stream.Flush($true) } finally { $stream.Dispose() }
    Move-Item -LiteralPath $temporary -Destination $Path -Force
}

function Write-DurableJson {
    param([string] $Path, [object] $Value)
    Write-DurableText -Path $Path -Content (($Value | ConvertTo-Json -Depth 8 -Compress) + "`n")
}

function Read-Json {
    param([string] $Path, [switch] $Optional)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        if ($Optional) { return $null }
        throw "devloop-install: error: metadata is missing: $Path"
    }
    Assert-PlainPath -Path $Path
    try { return Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json }
    catch { throw "devloop-install: error: metadata is unreadable: $Path" }
}

function Get-StringFingerprint {
    param([string[]] $Entries)
    $algorithm = [Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes($Entries -join "`n")
        return [BitConverter]::ToString($algorithm.ComputeHash($bytes)).Replace('-', '')
    }
    finally { $algorithm.Dispose() }
}

function Get-DirectoryFingerprint {
    param([string] $Path)
    Assert-PlainPath -Path $Path
    $prefix = $Path.TrimEnd('\') + '\'
    $files = @((Get-ChildItem -LiteralPath $Path -File -Recurse -Force).FullName)
    [Array]::Sort($files, [StringComparer]::Ordinal)
    $entries = foreach ($file in $files) {
        Assert-PlainPath -Path $file
        "$($file.Substring($prefix.Length).Replace('\', '/'))=$((Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash)"
    }
    return Get-StringFingerprint -Entries $entries
}

function Get-TrackedFingerprint {
    param([string] $Root)
    $entries = @(& git -C $Root ls-files --stage)
    if ($LASTEXITCODE -ne 0) { throw 'devloop-install: error: could not enumerate tracked release files' }
    [Array]::Sort($entries, [StringComparer]::Ordinal)
    return Get-StringFingerprint -Entries $entries
}

function Get-ReleaseEvidence {
    param([string] $Root, [string] $ExpectedCommit)
    Assert-PlainPath -Path $Root
    Assert-PlainPath -Path (Join-Path $Root '.git')
    $commit = (& git -C $Root rev-parse HEAD).Trim()
    if ($LASTEXITCODE -ne 0 -or $commit -cne $ExpectedCommit) { throw 'devloop-install: error: release commit changed during validation' }
    & git -C $Root diff --quiet --
    if ($LASTEXITCODE -ne 0) { throw 'devloop-install: error: release has tracked changes' }
    & git -C $Root diff --cached --quiet --
    if ($LASTEXITCODE -ne 0) { throw 'devloop-install: error: release has staged changes' }
    $unexpected = @(& git -C $Root ls-files --others --exclude-standard | Where-Object { -not $_.Replace('\', '/').StartsWith('.venv/') })
    if ($LASTEXITCODE -ne 0 -or $unexpected.Count -ne 0) { throw 'devloop-install: error: release has unexpected untracked content' }
    return [ordered]@{
        tracked_fingerprint = Get-TrackedFingerprint -Root $Root
        runtime_fingerprint = Get-DirectoryFingerprint -Path (Join-Path $Root '.venv')
    }
}

function Invoke-ReleaseCommand {
    param([string] $Python, [string] $Root, [string] $Command)
    $oldPythonPath = $env:PYTHONPATH
    $oldNoBytecode = $env:PYTHONDONTWRITEBYTECODE
    try {
        $env:PYTHONPATH = Join-Path $Root 'src'
        $env:PYTHONDONTWRITEBYTECODE = '1'
        & $Python -m devloop.portable_release $Command
        if ($LASTEXITCODE -ne 0) { throw "devloop-install: error: portable release $Command failed" }
    }
    finally {
        $env:PYTHONPATH = $oldPythonPath
        $env:PYTHONDONTWRITEBYTECODE = $oldNoBytecode
    }
}

function Clone-Candidate {
    $parent = Split-Path -Parent $InstallDir
    $leaf = Split-Path -Leaf $InstallDir
    $script:CandidateDir = Join-Path $parent ".${leaf}.candidate-$([guid]::NewGuid().ToString('N'))"
    Write-InstallLog "Staging ref $Ref outside the stable bootstrap"
    & git clone --depth 1 --branch $Ref $RepoUrl $script:CandidateDir
    if ($LASTEXITCODE -ne 0) {
        if (Test-Path -LiteralPath $script:CandidateDir) { Remove-Item -LiteralPath $script:CandidateDir -Recurse -Force }
        & git clone --depth 1 $RepoUrl $script:CandidateDir
        if ($LASTEXITCODE -ne 0) { throw "devloop-install: error: could not clone $RepoUrl" }
        & git -C $script:CandidateDir checkout -f $Ref
        if ($LASTEXITCODE -ne 0) { throw "devloop-install: error: could not resolve ref $Ref" }
    }
    $script:CandidateCommit = (& git -C $script:CandidateDir rev-parse HEAD).Trim()
    if ($LASTEXITCODE -ne 0 -or $script:CandidateCommit -cnotmatch '^[0-9a-f]{40}$') { throw 'devloop-install: error: candidate commit is invalid' }
    & git -C $script:CandidateDir reset --hard $script:CandidateCommit
    & git -C $script:CandidateDir clean -ffdx
    if ($LASTEXITCODE -ne 0) { throw 'devloop-install: error: could not clean candidate' }
}

function Install-CandidateRuntime {
    $runtime = Join-Path $script:CandidateDir '.venv'
    if ($env:DEVLOOP_TESTING -eq '1') {
        Invoke-ReleaseCommand -Python (Get-DevLoopPython) -Root $script:CandidateDir -Command 'validate-runtime'
        New-Item -ItemType Directory -Path $runtime | Out-Null
        [IO.File]::WriteAllText((Join-Path $runtime '.devloop-test-runtime'), $script:CandidateCommit, [Text.UTF8Encoding]::new($false))
        return
    }
    $basePython = Get-DevLoopPython
    & $basePython -m venv $runtime
    if ($LASTEXITCODE -ne 0) { throw 'devloop-install: error: runtime creation failed' }
    $python = Join-Path $runtime 'Scripts\python.exe'
    & $python -m pip install --disable-pip-version-check --requirement (Join-Path $script:CandidateDir 'requirements-portable.lock')
    if ($LASTEXITCODE -ne 0) { throw 'devloop-install: error: runtime dependency installation failed' }
    Invoke-ReleaseCommand -Python $python -Root $script:CandidateDir -Command 'validate-runtime'
}

function Get-BootstrapTargets {
    param([string] $CandidateRoot)
    $template = Join-Path $CandidateRoot 'install\bootstrap'
    if (-not (Test-Path -LiteralPath $template -PathType Container)) { throw 'devloop-install: error: candidate has no stable bootstrap templates' }
    return @(
        @{ Source = Join-Path $template 'dispatch.ps1'; Relative = 'bootstrap\dispatch.ps1' },
        @{ Source = Join-Path $template 'dispatch.sh'; Relative = 'bootstrap\dispatch.sh' },
        @{ Source = Join-Path $template 'verify.py'; Relative = 'bootstrap\verify.py' },
        @{ Source = Join-Path $template 'transaction.py'; Relative = 'bootstrap\transaction.py' },
        @{ Source = Join-Path $template 'bin\devloop.ps1'; Relative = 'bin\devloop.ps1' },
        @{ Source = Join-Path $template 'bin\devloop-plan.ps1'; Relative = 'bin\devloop-plan.ps1' },
        @{ Source = Join-Path $template 'bin\devloop.sh'; Relative = 'bin\devloop.sh' },
        @{ Source = Join-Path $template 'bin\devloop-plan.sh'; Relative = 'bin\devloop-plan.sh' },
        @{ Source = Join-Path $template 'install\devloop.ps1'; Relative = 'install\devloop.ps1' },
        @{ Source = Join-Path $template 'install\uninstall-devloop.ps1'; Relative = 'install\uninstall-devloop.ps1' },
        @{ Source = Join-Path $template 'install\devloop.sh'; Relative = 'install\devloop.sh' },
        @{ Source = Join-Path $template 'install\uninstall-devloop.sh'; Relative = 'install\uninstall-devloop.sh' }
    )
}

function Initialize-Bootstrap {
    param([string] $CandidateRoot)
    New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
    foreach ($relative in @('bootstrap', 'bootstrap\legacy-assets', 'releases', 'bin', 'install')) {
        $path = Join-Path $InstallDir $relative
        if (Test-Path -LiteralPath $path) { Assert-PlainPath -Path $path }
        else { New-Item -ItemType Directory -Path $path | Out-Null }
    }
    $layoutPath = Join-Path $InstallDir 'bootstrap\layout.json'
    $targets = Get-BootstrapTargets -CandidateRoot $CandidateRoot
    if (Test-Path -LiteralPath $layoutPath) {
        $layout = Read-Json -Path $layoutPath
        if ($layout.version -ne $LayoutVersion) { throw 'devloop-install: error: unsupported bootstrap layout version' }
        foreach ($target in $targets) {
            $relativeKey = $target.Relative.Replace('\', '/')
            $destination = Join-Path $InstallDir $target.Relative
            if (-not (Test-Path -LiteralPath $destination -PathType Leaf)) { throw "devloop-install: error: stable bootstrap asset is missing: $($target.Relative)" }
            $property = $layout.assets.PSObject.Properties[$relativeKey]
            if ($null -eq $property -or (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash -cne $property.Value) { throw "devloop-install: error: stable bootstrap asset was modified: $($target.Relative)" }
        }
        return
    }
    $assetHashes = [ordered]@{}
    $backups = @()
    foreach ($target in $targets) {
        $relative = $target.Relative
        $destination = Join-Path $InstallDir $relative
        Assert-PlainPath -Path $target.Source
        if (Test-Path -LiteralPath $destination) {
            Assert-PlainPath -Path $destination
            $backup = Join-Path $InstallDir ("bootstrap\legacy-assets\" + $relative)
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $backup) | Out-Null
            if (-not (Test-Path -LiteralPath $backup)) {
                Copy-Item -LiteralPath $destination -Destination $backup
            }
            $backups += $relative.Replace('\', '/')
            if ($env:DEVLOOP_TESTING -eq '1' -and $env:DEVLOOP_TEST_INTERRUPT_BOOTSTRAP_AFTER_BACKUP -eq '1') {
                [Environment]::Exit(93)
            }
        }
        Copy-Item -LiteralPath $target.Source -Destination $destination -Force
        $assetHashes[$relative.Replace('\', '/')] = (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash
    }
    Write-DurableJson -Path $layoutPath -Value ([ordered]@{ version = $LayoutVersion; assets = $assetHashes; legacy_backups = $backups })
}

function Get-CurrentPointer {
    $pointer = Read-Json -Path (Join-Path $InstallDir 'bootstrap\current.json') -Optional
    if ($null -eq $pointer) { return $null }
    $fields = @($pointer.PSObject.Properties.Name | Sort-Object)
    if (($fields -join ',') -ne 'commit,release_path,runtime_fingerprint,tracked_fingerprint,version' -or $pointer.version -ne 1 -or $pointer.commit -cnotmatch '^[0-9a-f]{40}$' -or $pointer.release_path -cne "releases/$($pointer.commit)") { throw 'devloop-install: error: current pointer is invalid' }
    return $pointer
}

function Write-Journal {
    param([object] $Journal, [string] $Phase)
    $Journal.phase = $Phase
    Write-DurableJson -Path (Join-Path $InstallDir 'bootstrap\install-transaction.json') -Value $Journal
    if ($env:DEVLOOP_TESTING -eq '1' -and $env:DEVLOOP_TEST_INTERRUPT_AFTER_PHASE -eq $Phase) { [Environment]::Exit(91) }
}

function Assert-Journal {
    param([object] $Journal)
    $fields = @($Journal.PSObject.Properties.Name | Sort-Object)
    if (($fields -join ',') -ne 'candidate_path,commit,install_root,phase,previous_pointer,release_path,runtime_fingerprint,tracked_fingerprint,version') { throw 'devloop-install: error: installation journal has an unsupported schema' }
    if ($Journal.version -ne $JournalVersion -or $Journal.commit -cnotmatch '^[0-9a-f]{40}$') { throw 'devloop-install: error: installation journal identity is invalid' }
    if (-not [string]::Equals([IO.Path]::GetFullPath($Journal.install_root), $InstallDir, [StringComparison]::OrdinalIgnoreCase)) { throw 'devloop-install: error: installation journal root mismatch' }
    $expectedRelease = [IO.Path]::GetFullPath((Join-Path $InstallDir "releases\$($Journal.commit)"))
    if (-not [string]::Equals([IO.Path]::GetFullPath($Journal.release_path), $expectedRelease, [StringComparison]::OrdinalIgnoreCase)) { throw 'devloop-install: error: installation journal release path is not owned' }
    $candidate = [IO.Path]::GetFullPath($Journal.candidate_path)
    $parent = [IO.Path]::GetFullPath((Split-Path -Parent $InstallDir)).TrimEnd('\')
    $candidateLeaf = Split-Path -Leaf $candidate
    $expectedLeaf = '^\.' + [regex]::Escape((Split-Path -Leaf $InstallDir)) + '\.candidate-[0-9a-f]{32}$'
    if ((Split-Path -Parent $candidate) -ine $parent -or $candidateLeaf -cnotmatch $expectedLeaf) { throw 'devloop-install: error: installation journal candidate path is not owned' }
    if ($Journal.phase -notin @('prepared', 'release_ready', 'adopted', 'switched', 'committed')) { throw 'devloop-install: error: installation journal phase is unsupported' }
    if ($Journal.tracked_fingerprint -cnotmatch '^[0-9A-F]{64}$' -or $Journal.runtime_fingerprint -cnotmatch '^[0-9A-F]{64}$') { throw 'devloop-install: error: installation journal fingerprint is invalid' }
}

function Write-ReleaseManifest {
    param([object] $Journal)
    Write-DurableJson -Path (Join-Path $InstallDir "bootstrap\release-$($Journal.commit).json") -Value ([ordered]@{
        version = 1
        commit = $Journal.commit
        release_path = "releases/$($Journal.commit)"
        tracked_fingerprint = $Journal.tracked_fingerprint
        runtime_fingerprint = $Journal.runtime_fingerprint
    })
}

function Assert-JournalRelease {
    param([object] $Journal)
    Assert-Journal -Journal $Journal
    $evidence = Get-ReleaseEvidence -Root $Journal.release_path -ExpectedCommit $Journal.commit
    if ($evidence.tracked_fingerprint -cne $Journal.tracked_fingerprint -or $evidence.runtime_fingerprint -cne $Journal.runtime_fingerprint) { throw 'devloop-install: error: immutable release fingerprint mismatch' }
}

function Initialize-UserState {
    param([string] $ReleaseRoot)
    $python = if ($env:DEVLOOP_TESTING -eq '1') { Get-DevLoopPython } else { Join-Path $ReleaseRoot '.venv\Scripts\python.exe' }
    Write-InstallLog 'Initializing v3 user state and idempotent v0.2.1 adoption'
    Invoke-ReleaseCommand -Python $python -Root $ReleaseRoot -Command 'prepare-user-state'
}

function Switch-CurrentPointer {
    param([object] $Journal)
    Assert-JournalRelease -Journal $Journal
    if ($env:DEVLOOP_TESTING -eq '1' -and $env:DEVLOOP_TEST_MUTATE_CANDIDATE_AFTER_VALIDATION -eq '1') {
        [IO.File]::AppendAllText((Join-Path $Journal.release_path 'release-marker'), "tampered`n")
    }
    $current = Get-CurrentPointer
    if ($null -ne $current -and $current.commit -cne $Journal.commit) {
        $oldRelease = Join-Path $InstallDir $current.release_path.Replace('/', '\')
        $oldEvidence = Get-ReleaseEvidence -Root $oldRelease -ExpectedCommit $current.commit
        if ($oldEvidence.tracked_fingerprint -cne $current.tracked_fingerprint -or $oldEvidence.runtime_fingerprint -cne $current.runtime_fingerprint) { throw 'devloop-install: error: current release changed during update; preserved without switching' }
        if ($env:DEVLOOP_TESTING -eq '1' -and $env:DEVLOOP_TEST_MUTATE_CURRENT_AFTER_FINAL_CHECK -eq '1') {
            [IO.File]::WriteAllBytes((Join-Path $oldRelease 'operator-race.bin'), [byte[]]@(114, 97, 99, 101, 0, 255))
        }
        Write-DurableJson -Path (Join-Path $InstallDir 'bootstrap\previous.json') -Value $current
    }
    Assert-JournalRelease -Journal $Journal
    Write-DurableJson -Path (Join-Path $InstallDir 'bootstrap\current.json') -Value ([ordered]@{
        version = 1
        commit = $Journal.commit
        release_path = "releases/$($Journal.commit)"
        tracked_fingerprint = $Journal.tracked_fingerprint
        runtime_fingerprint = $Journal.runtime_fingerprint
    })
    Write-Journal -Journal $Journal -Phase 'switched'
    Write-Journal -Journal $Journal -Phase 'committed'
    Remove-Item -LiteralPath (Join-Path $InstallDir 'bootstrap\install-transaction.json') -Force
}

function Finish-Journal {
    param([object] $Journal)
    Assert-Journal -Journal $Journal
    if ($Journal.phase -eq 'prepared') {
        if (Test-Path -LiteralPath $Journal.release_path) { throw 'devloop-install: error: release unexpectedly exists during prepared recovery' }
        Assert-PlainPath -Path $Journal.candidate_path
        if ($env:DEVLOOP_TESTING -eq '1' -and $env:DEVLOOP_TEST_MUTATE_PREPARED_CANDIDATE -eq '1') {
            [IO.File]::AppendAllText((Join-Path $Journal.candidate_path 'release-marker'), "tampered`n")
        }
        $candidateEvidence = Get-ReleaseEvidence -Root $Journal.candidate_path -ExpectedCommit $Journal.commit
        if ($candidateEvidence.tracked_fingerprint -cne $Journal.tracked_fingerprint -or $candidateEvidence.runtime_fingerprint -cne $Journal.runtime_fingerprint) { throw 'devloop-install: error: prepared candidate fingerprint mismatch' }
        Move-Item -LiteralPath $Journal.candidate_path -Destination $Journal.release_path
        Write-ReleaseManifest -Journal $Journal
        Write-Journal -Journal $Journal -Phase 'release_ready'
    }
    if ($Journal.phase -eq 'release_ready') {
        Assert-JournalRelease -Journal $Journal
        Initialize-UserState -ReleaseRoot $Journal.release_path
        Write-Journal -Journal $Journal -Phase 'adopted'
    }
    if ($Journal.phase -eq 'adopted') { Switch-CurrentPointer -Journal $Journal; return }
    if ($Journal.phase -in @('switched', 'committed')) {
        $current = Get-CurrentPointer
        if ($null -eq $current -or $current.commit -cne $Journal.commit) { throw 'devloop-install: error: journal says switched but current pointer disagrees' }
        Assert-JournalRelease -Journal $Journal
        if ($Journal.phase -eq 'switched') { Write-Journal -Journal $Journal -Phase 'committed' }
        Remove-Item -LiteralPath (Join-Path $InstallDir 'bootstrap\install-transaction.json') -Force
    }
}

function Recover-PendingTransaction {
    $journal = Read-Json -Path (Join-Path $InstallDir 'bootstrap\install-transaction.json') -Optional
    if ($null -eq $journal) { return $false }
    Write-InstallLog "Recovering durable installation phase $($journal.phase)"
    Finish-Journal -Journal $journal
    return $true
}

function Invoke-ReleaseRollback {
    if (Test-Path -LiteralPath (Join-Path $InstallDir 'bootstrap\install-transaction.json')) {
        throw 'devloop-install: error: finish the pending update before rollback'
    }
    $current = Get-CurrentPointer
    $previous = Read-Json -Path (Join-Path $InstallDir 'bootstrap\previous.json')
    $fields = @($previous.PSObject.Properties.Name | Sort-Object)
    if (($fields -join ',') -ne 'commit,release_path,runtime_fingerprint,tracked_fingerprint,version' -or $previous.version -ne 1 -or $previous.commit -cnotmatch '^[0-9a-f]{40}$' -or $previous.release_path -cne "releases/$($previous.commit)") {
        throw 'devloop-install: error: previous release pointer is invalid'
    }
    foreach ($pointer in @($current, $previous)) {
        $root = Join-Path $InstallDir $pointer.release_path.Replace('/', '\')
        $evidence = Get-ReleaseEvidence -Root $root -ExpectedCommit $pointer.commit
        if ($evidence.tracked_fingerprint -cne $pointer.tracked_fingerprint -or $evidence.runtime_fingerprint -cne $pointer.runtime_fingerprint) {
            throw 'devloop-install: error: rollback release fingerprint mismatch'
        }
    }
    Write-DurableJson -Path (Join-Path $InstallDir 'bootstrap\current.json') -Value $previous
    Write-DurableJson -Path (Join-Path $InstallDir 'bootstrap\previous.json') -Value $current
    Write-InstallLog "Rolled back current release to $($previous.commit)"
}

function Activate-Candidate {
    $evidence = Get-ReleaseEvidence -Root $script:CandidateDir -ExpectedCommit $script:CandidateCommit
    Initialize-Bootstrap -CandidateRoot $script:CandidateDir
    $releasePath = Join-Path $InstallDir "releases\$script:CandidateCommit"
    if (Test-Path -LiteralPath $releasePath) { throw 'devloop-install: error: canonical release directory already exists without an active transaction' }
    $journal = [pscustomobject][ordered]@{
        version = $JournalVersion
        install_root = $InstallDir
        commit = $script:CandidateCommit
        candidate_path = [IO.Path]::GetFullPath($script:CandidateDir)
        release_path = [IO.Path]::GetFullPath($releasePath)
        tracked_fingerprint = $evidence.tracked_fingerprint
        runtime_fingerprint = $evidence.runtime_fingerprint
        previous_pointer = Get-CurrentPointer
        phase = 'prepared'
    }
    Write-Journal -Journal $journal -Phase 'prepared'
    Finish-Journal -Journal $journal
    $script:CandidateDir = $null
}

function Install-Capabilities {
    $pointer = Get-CurrentPointer
    $root = Join-Path $InstallDir $pointer.release_path.Replace('/', '\')
    if ($NoSkills) { return }
    try {
        if ($env:DEVLOOP_TESTING -eq '1' -and $env:DEVLOOP_TEST_CAPABILITY_FAILURE -eq '1') {
            throw 'injected capability installation failure'
        }
        & (Join-Path $root 'install\install-skills.ps1')
        if ($LASTEXITCODE -ne 0) { throw 'capability installer returned a failure' }
    }
    catch { Write-Warning "devloop-install: capability installation warning: $($_.Exception.Message)" }
}

function Show-NextSteps {
    $pointer = Get-CurrentPointer
    Write-Host ''
    Write-Host "Portable Dev Loop is installed at $InstallDir"
    Write-Host "Current immutable release: $($pointer.commit)"
    Write-Host "Run: & '$InstallDir\bin\devloop.ps1' --help"
    Write-Host "Plan: & '$InstallDir\bin\devloop-plan.ps1' --help"
    Write-Host "Update: & '$InstallDir\install\devloop.ps1'"
    Write-Host "Uninstall: & '$InstallDir\install\uninstall-devloop.ps1'"
}

if ($Help) { Show-Usage; return }
if ($null -eq (Get-Command git -ErrorAction SilentlyContinue)) { throw 'devloop-install: error: Git is required.' }
[void](Get-DevLoopPython)
$InstallDir = Resolve-InstallDirectory
Assert-SafeInstallRoot

if ($Rollback) {
    Invoke-ReleaseRollback
    Show-NextSteps
    return
}

if (Test-Path -LiteralPath (Join-Path $InstallDir 'bootstrap\layout.json')) {
    if (Recover-PendingTransaction) {
        Install-Capabilities
        Show-NextSteps
        return
    }
}

try {
    Clone-Candidate
    Install-CandidateRuntime
    $current = if (Test-Path -LiteralPath (Join-Path $InstallDir 'bootstrap\current.json')) { Get-CurrentPointer } else { $null }
    if ($null -ne $current -and $current.commit -ceq $script:CandidateCommit) {
        $currentRoot = Join-Path $InstallDir $current.release_path.Replace('/', '\')
        $currentEvidence = Get-ReleaseEvidence -Root $currentRoot -ExpectedCommit $current.commit
        if ($currentEvidence.tracked_fingerprint -cne $current.tracked_fingerprint -or $currentEvidence.runtime_fingerprint -cne $current.runtime_fingerprint) { throw 'devloop-install: error: current release fingerprint mismatch' }
        Remove-Item -LiteralPath $script:CandidateDir -Recurse -Force
        $script:CandidateDir = $null
        Initialize-UserState -ReleaseRoot $currentRoot
    }
    else { Activate-Candidate }
}
catch {
    $failure = $_
    $journalExists = Test-Path -LiteralPath (Join-Path $InstallDir 'bootstrap\install-transaction.json')
    if (-not $journalExists -and $null -ne $script:CandidateDir -and (Test-Path -LiteralPath $script:CandidateDir)) {
        Remove-Item -LiteralPath $script:CandidateDir -Recurse -Force
    }
    throw $failure
}
Install-Capabilities
Show-NextSteps

install/uninstall-devloop.ps1:
# Remove verified installer-owned bootstrap and immutable release assets.

[CmdletBinding()]
param(
    [string] $InstallDir = $(if ($env:DEVLOOP_INSTALL_DIR) { $env:DEVLOOP_INSTALL_DIR } else { Split-Path -Parent (Split-Path -Parent $PSScriptRoot) }),
    [string] $BinDir,
    [string] $CodexSkillsPath = "$env:USERPROFILE\.codex\skills",
    [string] $CodexAgentsPath = "$env:USERPROFILE\.codex\agents",
    [switch] $KeepSkills,
    [switch] $Help
)

$ErrorActionPreference = 'Stop'
$null = $BinDir

function Show-Usage {
    @'
Usage: uninstall-devloop.ps1 [options]

Remove verified installer-managed bootstrap and release assets. User state,
projects, legacy checkout files, and modified capabilities are preserved.
'@ | Write-Host
}

function Assert-PlainPath {
    param([string] $Path)
    $item = Get-Item -LiteralPath $Path -Force
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
        throw "devloop-uninstall: refusing reparse point: $Path"
    }
}

function Remove-MatchingCapabilities {
    param([string] $SourceRoot, [string] $DestinationRoot)
    if (-not (Test-Path -LiteralPath $SourceRoot -PathType Container)) { return }
    $prefix = $SourceRoot.TrimEnd('\') + '\'
    foreach ($source in Get-ChildItem -LiteralPath $SourceRoot -File -Recurse) {
        $destination = Join-Path $DestinationRoot $source.FullName.Substring($prefix.Length)
        if (-not (Test-Path -LiteralPath $destination -PathType Leaf)) { continue }
        if ((Get-FileHash -LiteralPath $source.FullName -Algorithm SHA256).Hash -cne (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash) {
            Write-Host "Kept modified capability: $destination"
            continue
        }
        Remove-Item -LiteralPath $destination -Force
    }
}

if ($Help) { Show-Usage; return }
$InstallDir = [IO.Path]::GetFullPath($InstallDir).TrimEnd('\')
$root = [IO.Path]::GetPathRoot($InstallDir)
if ($InstallDir -ieq $root.TrimEnd('\')) { throw 'devloop-uninstall: refusing filesystem root' }
Assert-PlainPath -Path $InstallDir
$bootstrap = Join-Path $InstallDir 'bootstrap'
$layoutPath = Join-Path $bootstrap 'layout.json'
if (-not (Test-Path -LiteralPath $layoutPath -PathType Leaf)) {
    throw 'devloop-uninstall: stable layout manifest is missing; nothing was removed'
}
Assert-PlainPath -Path $bootstrap
Assert-PlainPath -Path $layoutPath
try { $layout = Get-Content -LiteralPath $layoutPath -Raw | ConvertFrom-Json }
catch { throw 'devloop-uninstall: layout manifest is unreadable; nothing was removed' }
if ($layout.version -ne 1) { throw 'devloop-uninstall: layout manifest version is unsupported; nothing was removed' }

# The stable verifier proves current pointer ownership, release canonicality,
# Git cleanliness, and both recorded fingerprints before any release deletion.
$verifier = Join-Path $bootstrap 'verify.py'
if (Test-Path -LiteralPath $verifier -PathType Leaf) {
    $python = $null
    foreach ($candidate in @('python', 'python3', 'py')) {
        if ($null -eq (Get-Command $candidate -ErrorAction SilentlyContinue)) { continue }
        try {
            & $candidate -c 'import sys; raise SystemExit(0 if sys.version_info >= (3, 10) else 1)' *> $null
            if ($LASTEXITCODE -eq 0) { $python = $candidate; break }
        }
        catch { continue }
    }
    if ($null -eq $python) { throw 'devloop-uninstall: Python 3.10+ is required to verify managed releases' }
    & $python $verifier $InstallDir | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'devloop-uninstall: current release verification failed; nothing was removed' }
}

$activeRoot = Split-Path -Parent $PSScriptRoot
if (-not $KeepSkills) {
    Remove-MatchingCapabilities -SourceRoot (Join-Path $activeRoot 'skills\codex') -DestinationRoot $CodexSkillsPath
    Remove-MatchingCapabilities -SourceRoot (Join-Path $activeRoot 'agents\codex') -DestinationRoot $CodexAgentsPath
}

$releaseRoot = Join-Path $InstallDir 'releases'
Assert-PlainPath -Path $releaseRoot
foreach ($release in Get-ChildItem -LiteralPath $releaseRoot -Directory -Force) {
    Assert-PlainPath -Path $release.FullName
    if ($release.Name -cnotmatch '^[0-9a-f]{40}$') {
        throw "devloop-uninstall: unmanaged release directory blocks removal: $($release.FullName)"
    }
    $manifest = Join-Path $bootstrap "release-$($release.Name).json"
    if (-not (Test-Path -LiteralPath $manifest -PathType Leaf)) {
        throw "devloop-uninstall: release ownership manifest is missing: $($release.Name)"
    }
    if (Test-Path -LiteralPath $verifier -PathType Leaf) {
        & $python $verifier $InstallDir $release.Name | Out-Null
        if ($LASTEXITCODE -ne 0) {
            throw "devloop-uninstall: release verification failed; nothing was removed: $($release.Name)"
        }
    }
}
foreach ($release in Get-ChildItem -LiteralPath $releaseRoot -Directory -Force) {
    Remove-Item -LiteralPath $release.FullName -Recurse -Force
    Remove-Item -LiteralPath (Join-Path $bootstrap "release-$($release.Name).json") -Force
}

$legacyRoot = Join-Path $bootstrap 'legacy-assets'
foreach ($property in $layout.assets.PSObject.Properties) {
    $relative = $property.Name.Replace('/', '\')
    $target = Join-Path $InstallDir $relative
    $backup = Join-Path $legacyRoot $relative
    if (Test-Path -LiteralPath $target -PathType Leaf) {
        if ((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -eq $property.Value) {
            Remove-Item -LiteralPath $target -Force
        }
        else {
            Write-Host "Kept modified bootstrap asset: $target"
            continue
        }
    }
    if (Test-Path -LiteralPath $backup -PathType Leaf) {
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
        Move-Item -LiteralPath $backup -Destination $target
        Write-Host "Restored legacy entrypoint: $target"
    }
}

foreach ($path in @(
    (Join-Path $bootstrap 'current.json'),
    (Join-Path $bootstrap 'previous.json'),
    (Join-Path $bootstrap 'install-transaction.json'),
    $layoutPath
)) {
    if (Test-Path -LiteralPath $path -PathType Leaf) { Remove-Item -LiteralPath $path -Force }
}
foreach ($directory in @($releaseRoot, $legacyRoot, $bootstrap, (Join-Path $InstallDir 'bin'), (Join-Path $InstallDir 'install'))) {
    if ((Test-Path -LiteralPath $directory -PathType Container) -and @(Get-ChildItem -LiteralPath $directory -Force).Count -eq 0) {
        Remove-Item -LiteralPath $directory -Force
    }
}
Write-Host 'Dev Loop managed bootstrap and immutable releases were removed.'
Write-Host 'Portable catalog, project data, and legacy checkout content were preserved.'

src/devloop/portable_release.py:
from __future__ import annotations

import argparse
import json
import sqlite3
from dataclasses import dataclass
from pathlib import Path
from typing import Sequence

from .portable_project_adoption import (
    PortableAdoptionReport,
    PortableAdoptionStatus,
    adopt_v021_configuration,
)
from .portable_session_catalog import (
    PortableSessionCatalog,
    portable_session_catalog_path,
)
from .portable_version import (
    PORTABLE_GENERATION,
    PORTABLE_PRODUCT_NAME,
    PORTABLE_VERSION,
)
from .workflow_defaults import portable_planner_configuration_path

PORTABLE_TEXTUAL_VERSION = "8.2.8"
PORTABLE_RELEASE_METADATA = {
    "product": PORTABLE_PRODUCT_NAME,
    "generation": PORTABLE_GENERATION,
    "version": PORTABLE_VERSION,
    "codexcli": "separate product",
}


class PortableReleasePreparationError(RuntimeError):
    pass


@dataclass(frozen=True)
class PortableReleasePreparation:
    catalog_path: Path
    adoption_report: PortableAdoptionReport | None


@dataclass(frozen=True)
class PortableRuntimeValidation:
    textual_version: str
    sqlite_version: str


def _validate_release_metadata(bundle_root: Path) -> None:
    metadata_path = bundle_root / "portable-release.json"
    try:
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise PortableReleasePreparationError(
            f"Portable release metadata is unreadable: {metadata_path}: {error}"
        ) from error
    if metadata != PORTABLE_RELEASE_METADATA:
        raise PortableReleasePreparationError(
            "Portable release metadata does not match this runtime: "
            f"expected {PORTABLE_RELEASE_METADATA!r}, found {metadata!r}."
        )


def validate_portable_runtime(
    *,
    bundle_root: Path | None = None,
) -> PortableRuntimeValidation:
    _validate_release_metadata(
        bundle_root.resolve()
        if bundle_root is not None
        else Path(__file__).resolve().parents[2]
    )
    import textual

    if textual.__version__ != PORTABLE_TEXTUAL_VERSION:
        raise PortableReleasePreparationError(
            "Portable runtime Textual version is unsupported: "
            f"expected {PORTABLE_TEXTUAL_VERSION}, found {textual.__version__}."
        )
    if not sqlite3.sqlite_version:
        raise PortableReleasePreparationError(
            "Portable runtime standard-library SQLite is unavailable."
        )
    return PortableRuntimeValidation(textual.__version__, sqlite3.sqlite_version)


def prepare_portable_user_state(
    *,
    catalog_path: Path | None = None,
    configuration_path: Path | None = None,
) -> PortableReleasePreparation:
    selected_catalog_path = (
        catalog_path or portable_session_catalog_path()
    ).resolve()
    selected_configuration_path = (
        configuration_path or portable_planner_configuration_path()
    ).resolve()
    catalog = PortableSessionCatalog(selected_catalog_path)
    if not selected_configuration_path.exists():
        return PortableReleasePreparation(selected_catalog_path, None)

    report = adopt_v021_configuration(catalog, selected_configuration_path)
    unsupported = tuple(
        entry for entry in report.entries
        if entry.status is PortableAdoptionStatus.UNSUPPORTED
    )
    if unsupported:
        details = "; ".join(entry.detail for entry in unsupported)
        raise PortableReleasePreparationError(
            f"Portable v0.2.1 adoption could not complete: {details}"
        )
    return PortableReleasePreparation(selected_catalog_path, report)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="python -m devloop.portable_release",
        description="Validate and prepare the Portable Dev Loop v3 installation.",
    )
    parser.add_argument(
        "command",
        choices=("validate-runtime", "prepare-user-state"),
    )
    parser.add_argument("--catalog", type=Path)
    parser.add_argument("--configuration", type=Path)
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "validate-runtime":
        validate_portable_runtime()
    else:
        prepare_portable_user_state(
            catalog_path=args.catalog,
            configuration_path=args.configuration,
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
